// src/components/PolicyCard.js
import React, { useState } from "react";
const { v4: uuidv4 } = require("uuid");


const PolicyCard = ({ onPolicyDataChange }) => {
  const [policyData, setPolicyData] = useState({
    policyNumber: "123456789",
    insuredName: "Juan Pérez",
    validity: "01/01/2023 - 31/12/2023",
    insuranceType: "Automóvil",
    status: "Activa",
  });

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setPolicyData({ ...policyData, [name]: value });
    onPolicyDataChange({ ...policyData, [name]: value }); // Enviar datos actualizados al componente padre
  };

  return (
    <div className="policy-card">
      <h2>Información de la Póliza</h2>
      <div className="policy-details">
        <p>
          <strong>Número de Póliza:</strong>
          <input
            type="text"
            name="policyNumber"
            value={policyData.policyNumber}
            onChange={handleInputChange}
          />
        </p>
        <p>
          <strong>Nombre del Asegurado:</strong>
          <input
            type="text"
            name="insuredName"
            value={policyData.insuredName}
            onChange={handleInputChange}
          />
        </p>
        <p>
          <strong>Vigencia:</strong>
          <input
            type="text"
            name="validity"
            value={policyData.validity}
            onChange={handleInputChange}
          />
        </p>
        <p>
          <strong>Tipo de Seguro:</strong>
          <input
            type="text"
            name="insuranceType"
            value={policyData.insuranceType}
            onChange={handleInputChange}
          />
        </p>
        <p>
          <strong>Estado:</strong>
          <input
            type="text"
            name="status"
            value={policyData.status}
            onChange={handleInputChange}
          />
        </p>
      </div>
    </div>
  );
};

export default PolicyCard;
